async function onHiuHiOnRequest(db:Db,_h:any,b:any){const hr=b.hiRequest||{};const t=(await db.query("select * from abdm_hi_transfers where request_id=$1 and role='hiu'",[String(rid(b)||'')])).rows[0];if(!t)return {error:'Unknown request'};await db.query("update abdm_hi_transfers set transaction_id=coalesce($2,transaction_id),status=case when status='RECEIVED' then status else $3 end,error=$4,updated_at=now() where id=$1",[t.id,hr.transactionId||null,b.error?'ERROR':String(hr.sessionStatus||'ACKNOWLEDGED'),b.error?errMsg(b.error):null]);return {hid:t.hospital_id}}
