export async function listConsents(db:Db,ctx:Ctx){requireRole(ctx,['admin','doctor']);return (await db.query("select c.*,p.uhid,p.full_name,u.full_name requested_by,(select count(*) from abdm_consent_artefacts a where a.consent_id=c.id)::int artefacts,(select count(*) from abdm_hi_records r join abdm_hi_transfers t on t.id=r.transfer_id join abdm_consent_artefacts a on a.artefact_id=t.artefact_id and a.hospital_id=t.hospital_id and a.role='hiu' where a.consent_id=c.id and r.bundle is not null)::int records from abdm_consents c left join patients p on p.id=c.patient_id left join users u on u.id=c.created_by where c.hospital_id=$1 order by c.created_at desc limit 200",[ctx.hospitalId])).rows}
